import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ClassUtils.getShortClassName
 */
public class ClassUtils_getShortClassName_TriageGen0Test {

    private static final String EMPTY = "";

    @Test
    public void testGetShortClassName_NullInput() {
        assertEquals(EMPTY, ClassUtils.getShortClassName(null));
    }

    @Test
    public void testGetShortClassName_EmptyInput() {
        assertEquals(EMPTY, ClassUtils.getShortClassName(""));
    }

    @Test
    public void testGetShortClassName_SimpleClass() {
        // Test case where there are no dots (no package)
        assertEquals("String", ClassUtils.getShortClassName("String"));
    }

    @Test
    public void testGetShortClassName_WithPackage() {
        // Test case with package: lastDotIdx will be found
        assertEquals("String", ClassUtils.getShortClassName("java.lang.String"));
    }

    @Test
    public void testGetShortClassName_WithInnerClass() {
        // Test case with inner class: should replace '$' with '.' 
        // Based on the logic: out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
        // Assuming INNER_CLASS_SEPARATOR_CHAR is '$' and PACKAGE_SEPARATOR_CHAR is '.'
        assertEquals("Inner.Class", ClassUtils.getShortClassName("com.example.Outer$Inner.Class"));

        // Test case where inner class is at the end
        assertEquals("Outer$Inner", ClassUtils.getShortClassName("com.example.Outer$Inner"));
    }

    @Test
    public void testGetShortClassName_ComplexPath() {
        // Test case with multiple dots and an inner class
        // lastDotIdx of 'java.lang.String' is at index 9. 
        // innerIdx searches after index 10.
        assertEquals("My.Inner.Class", ClassUtils.getShortClassName("org.apache.commons.My$Inner.Class"));
    }

    @Test
    public void testGetShortClassName_NoDotsNoInner() {
        assertEquals("MyClass", ClassUtils.getShortClassName("MyClass"));
    }

    @Test
    public void testGetShortClassName_OnlyDots() {
        // Edge case: string with dots but no actual class name at the end
        // If input is "a.b.", lastDotIdx is 3. substring(4) is empty.
        assertEquals("", ClassUtils.getShortClassName("a.b."));
    }

    @Test
    public void testGetShortClassName_InnerClassWithoutPackage() {
        // Test case where there is no package, but there is an inner class separator
        // lastDotIdx = -1. innerIdx = indexOf('$', 0).
        // out = className.substring(0) -> "Outer$Inner"
        // innerIdx != -1, so out = "Outer.Inner"
        assertEquals("Outer.Inner", ClassUtils.getShortClassName("Outer$Inner"));
    }
}
